import{z as E,x as d,o as t,c as h,q as n,j as l,D as e,d as A,s as o,S as s,b as i}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"Multi-Query Attention","description":"","frontmatter":{"title":"Multi-Query Attention","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/mqa.md","filePath":"llm/mqa.md","lastUpdated":1791413859000}'),B={name:"llm/mqa.md"};function m(p,a,u,M,c,K){const r=d("Mermaid");return t(),h("div",null,[a[2]||(a[2]=n('<h1 id="multi-query-attention" tabindex="-1">Multi-Query Attention <a class="header-anchor" href="#multi-query-attention" aria-label="Permalink to &quot;Multi-Query Attention&quot;">​</a></h1><div class="epigraph"><p>在多头自注意力里，键和值可以在所有查询头之间共享；解码时每步只需写出并读回一套 KV，带宽随头数下降。</p><footer>—— Shazeer, Fast Transformer Decoding: One Write-Head is All You Need, 2019</footer></div><p><a href="/llm/attention-quadratic-cost">上一课</a>已经说明：解码第 \\(n\\) 步仍要对 \\(n\\) 个键做点积，KV 缓存把二次问题转成「搬历史」。本课不重讲 \\(O(n^2)\\)，也不重讲多头怎么拼。<a href="/llm/mha">多头</a>为每个头准备独立的键、值，质量好，但每生成一个词都要把 \\(h\\) 组历史 KV 从 HBM 读回来。Shazeer 在 2019 年把查询头留下、键值头减到一套——Multi-Query Attention（MQA）。它砍的是线性项里与头数相乘的系数，不是二次阶。下一课才在「一头」和「每头独立」之间插入分组。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/llm/attention-quadratic-cost">二次复杂度</a>已经把解码写成带宽界：新查询只有一条，真正贵的是加载 \\(K_{1:t},V_{1:t}\\)。完整 MHA 的缓存是 \\([t, h, d_k]\\) 的键加同样形状的值，字节数与 \\(h\\) 成正比。头数随模型变宽而增加时，单步延迟越来越像「搬历史」而不是「做点积」。批大小一大，并发再乘以 \\(h\\)。缺口是：能不能在不放弃多套查询路由的前提下，把要搬的 KV 头数压到 1。</p><p>Shazeer 的观察是：许多任务上，各头的查询方向差异比键值方向差异更重要。查询负责「这一头在问什么」，键值负责「上下文里有什么可被问」。后者在头之间高度相关，独立存储的收益递减，读取成本却线性上涨。MQA 把这一观察做成硬约束：键值头数等于 1。</p><h3 id="带宽界而不是算术界" tabindex="-1">带宽界而不是算术界 <a class="header-anchor" href="#带宽界而不是算术界" aria-label="Permalink to &quot;带宽界而不是算术界&quot;">​</a></h3><p>令带宽为 \\(B\\) 字节每秒，单步要读 \\(2\\cdot t\\cdot h\\cdot d_k\\cdot b\\) 字节（\\(b\\) 为每元素字节）。算术量大约是 \\(2\\cdot t\\cdot h\\cdot d_k\\) 次乘加。算术强度随实现细节变化，但对解码往往低到被带宽饱和。把 \\(h\\) 换成 \\(1\\)，读量降到约 \\(1/h\\)，算术量若查询头仍为 \\(h\\) 则点积次数不变——查询仍有 \\(h\\) 条，只是它们点积同一份 \\(K\\)。于是算术强度上升，计算单元开始吃得饱。这是 MQA 的直接目标。<span class="marginnote">数字实例：取 \\(h=32\\)、\\(d_k=128\\)、每元素 2 字节（BF16）、已生成 \\(t=4096\\) 个 token。MHA 每步要读 \\(2\\times4096\\times32\\times128\\times2\\approx67\\) MB 的 KV；MQA 只读 \\(2\\times4096\\times1\\times128\\times2\\approx2.1\\) MB——约 1/32。若 HBM 带宽 2 TB/s，仅搬 KV 这一项就从约 33 微秒压到约 1 微秒。</span></p><p><span class="marginnote">MQA 不缩短序列，也不改变 softmax 对 \\(t\\) 个位置求和这一事实。第 \\(n\\) 步仍与 \\(n\\) 成线性关系。它削减的是线性项的系数里与头数相乘的那一段。窗口注意力减的是 \\(n\\)，MQA 减的是 \\(h_{\\mathrm{KV}}\\)，两者正交，可以叠用。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>设查询头数为 \\(h\\)，键值头数为 1。输入 \\(X\\) 仍投影出 \\(Q\\in\\mathbb{R}^{n\\times h\\times d_k}\\)，但</p> \\[K=XW^K,\\qquad V=XW^V, \\]<p>\\(W^K,W^V\\in\\mathbb{R}^{d\\times d_k}\\)，得到 \\(K,V\\in\\mathbb{R}^{n\\times 1\\times d_k}\\)。每个查询头 \\(i\\) 计算</p> \\[\\mathrm{head}_i=\\mathrm{softmax}\\left(\\frac{Q_i K^\\top}{\\sqrt{d_k}}\\right)V, \\]<p>即 \\(h\\) 套分数、同一份键值。拼头后的 \\(W^O\\) 与 MHA 相同。因果掩码、缩放规则都不改。训练时 \\(K,V\\) 在序列维上仍可一次算完；解码时缓存只追加形状 \\([1,d_k]\\) 的一对向量，而不是 \\([h,d_k]\\)。</p><h3 id="从已有-mha-检查点出发" tabindex="-1">从已有 MHA 检查点出发 <a class="header-anchor" href="#从已有-mha-检查点出发" aria-label="Permalink to &quot;从已有 MHA 检查点出发&quot;">​</a></h3><p>若直接随机初始化 MQA 训练，当然可以。若要从已有多头检查点改，需要把 \\(h\\) 组 \\(W^K_i,W^V_i\\) 收成一组。简单平均或只保留一头都会造成瞬时质量下跌，通常要再做一段上训练（uptraining）让查询头适应共享记忆。Shazeer 原文的设定是为加速解码而设计的结构，不一定从 MHA 蒸馏；后来的 GQA 论文把「从 MHA 平均 KV 头再短训」变成标准工序。MQA 可以看成 GQA 在组数等于 1 时的端点。</p>',17)),(t(),l(s,null,{default:e(()=>[o(r,{id:"mermaid-45",class:"mermaid",graph:"flowchart%20LR%0A%20%20X%5B%22%E8%BE%93%E5%85%A5%22%5D%20--%3E%20Q%5B%22h%20%E5%A5%97%20Query%20%E5%A4%B4%22%5D%0A%20%20X%20--%3E%20KV%5B%22%E4%B8%80%E5%A5%97%E5%85%B1%E4%BA%AB%20Key%20Value%22%5D%0A%20%20Q%20--%3E%20A%5B%22%E5%90%84%E5%A4%B4%E5%AF%B9%E5%90%8C%E4%B8%80%20K%20%E6%89%93%E5%88%86%22%5D%0A%20%20KV%20--%3E%20A%0A%20%20A%20--%3E%20C%5B%22%E6%8B%BC%E6%8E%A5%E5%B9%B6%E8%BE%93%E5%87%BA%E6%8A%95%E5%BD%B1%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[A(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=i("h2",{id:"机制",tabindex:"-1"},[A("机制 "),i("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=i("p",null,"共享 KV 意味着所有查询头在同一个键几何里检索。头与头的差异只能来自 \\(Q_i\\) 与 \\(W^O\\) 的对应块：它们可以对同一组键打出不同的分数分布，从而读出不同的值混合——注意值也只有一份，不同混合来自不同权重，而不是来自不同的值子空间。与 MHA 相比，值侧的子空间多样性被关掉，路由多样性还在。这解释了为何质量往往「可用、但略差」：内容库变薄，提问方式仍多。",-1)),(t(),l(s,null,{default:e(()=>[o(r,{id:"mermaid-52",class:"mermaid",graph:"flowchart%20TD%0A%20%20subgraph%20MHA%5B%22MHA%EF%BC%9A%E6%AF%8F%E5%A4%B4%E7%8B%AC%E7%AB%8B%E9%94%AE%E5%80%BC%22%5D%0A%20%20%20%20QA%5B%22%E5%A4%9A%E4%B8%AA%E6%9F%A5%E8%AF%A2%E5%A4%B4%22%5D%20--%3E%20KA%5B%22%E5%A4%9A%E5%A5%97%20K%2FV%20%E5%86%85%E5%AE%B9%E5%BA%93%20%E5%A4%B4%E9%97%B4%E7%8B%AC%E7%AB%8B%22%5D%0A%20%20%20%20KA%20--%3E%20OA%5B%22%E5%80%BC%E5%AD%90%E7%A9%BA%E9%97%B4%E6%8C%89%E5%A4%B4%E5%88%86%E5%8C%96%22%5D%0A%20%20end%0A%20%20subgraph%20MQAS%5B%22MQA%EF%BC%9A%E5%8D%95%E5%A5%97%E5%85%B1%E4%BA%AB%E9%94%AE%E5%80%BC%22%5D%0A%20%20%20%20QB%5B%22%E5%A4%9A%E4%B8%AA%E6%9F%A5%E8%AF%A2%E5%A4%B4%22%5D%20--%3E%20KB%5B%22%E5%90%8C%E4%B8%80%E4%BB%BD%20K%2FV%20%E5%86%85%E5%AE%B9%E5%BA%93%22%5D%0A%20%20%20%20KB%20--%3E%20OB%5B%22%E5%90%84%E5%A4%B4%E6%89%93%E4%B8%8D%E5%90%8C%E5%88%86%E6%95%B0%20%E8%AF%BB%E5%87%BA%E4%B8%8D%E5%90%8C%E5%8A%A0%E6%9D%83%22%5D%0A%20%20end%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[A(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=n('<p><span class="marginnote">直觉类比：MHA 像 32 位读者各有各的资料室，想找什么互不干扰；MQA 是 32 位读者共用同一间资料室——大家还是可以带着不同的问题进来（查询多样性保留），在同一排书架前翻出不同的重点（打分不同），但书架上总共就那么多书（值子空间变薄），谁也没法翻到别人那份独有收藏。</span></p><p>梯度上，\\(W^K,W^V\\) 会收到全部查询头的误差总和，更新更稳、也更折中。某个头若需要一种很偏的键方向，会与其他头打架。训练初期这种打架表现为损失略高、需要稍长的步数；训练后期则表现为某些细粒度对齐（稀有标记、精确位置）变弱。对解码器只语言模型，损失差通常小于翻译这类强对齐任务，这也是 MQA 先在自回归解码文献里站稳的原因。</p><p><span class="marginnote">实现时要把共享的 \\(K,V\\) 广播到 \\(h\\) 个头再做批量化点积，或使用允许「查询头多、键头少」的注意力核。错误地把 \\(K\\) 也扩成 \\(h\\) 头却共享存储指针，容易在反向里重复累加梯度。正确语义是：正向广播，反向对 KV 投影求和。</span></p><h3 id="前填收益有限、解码收益显著" tabindex="-1">前填收益有限、解码收益显著 <a class="header-anchor" href="#前填收益有限、解码收益显著" aria-label="Permalink to &quot;前填收益有限、解码收益显著&quot;">​</a></h3><p>前填阶段 \\(Q,K,V\\) 都从当前序列现场算，HBM 上的 KV 还不必反复读历史。MQA 减少的投影量只有 \\(K,V\\) 两张矩阵的宽度，前填加速通常是几个百分点。解码阶段历史只读不写投影，加速可以接近头数比。因此 MQA 是服务侧结构，不是训练吞吐结构。若工作负载几乎全是训练或超长前填、很少生成，MQA 的动机变弱。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>质量回归是核心代价。头数很大的模型把 KV 压到 1 头，等于让上百个查询共享一个内容库，困难任务、长依赖、需要多角度复制上下文的场景会先受伤。批很小、长度很短时，解码本就不是带宽界，MQA 几乎白付质量。批很大、长度很长时，缓存容量按 \\(1/h\\) 下降，同卡可服务的并发显著上升——产品上这往往比单请求的一点点困惑度更值钱。<span class="marginnote">常见误区：以为「换上 MQA 推理一定变快」。前填阶段 \\(K,V\\) 都是现场算的，MQA 只省两条投影矩阵的宽度，加速通常只有几个百分点；收益集中在解码步的 KV 读取。批小、序列短时解码本来就吃不满带宽，换 MQA 几乎白付质量——它是给「长序列、大并发」的服务场景准备的结构。</span></p><p>GQA 的出现说明业界不愿长期停在 MQA 这个端点：用 8 个 KV 头而不是 1 个，常能收回大部分质量，仍把缓存降到 MHA 的 \\(8/h\\)。MLA 则不愿共享头，而愿把每 token 的 KV 压进潜向量。选择 MQA，意味着明确接受「单内容库、多提问」。</p><p><span class="marginnote">MQA 与张量并行交互时，KV 头只有 1，不能再按头切分到多卡。查询头仍可切。这会让并行策略在注意力子层变得不对称。单机服务无此问题；多卡解码需要改切分方案或把 KV 复制到各卡。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>MQA 保留多套查询头，全头共享一套键值，解码 KV 缓存约为 MHA 的 \\(1/h\\)。</li><li>目标是提高解码算术强度、降低带宽与容量，不改变 softmax 对序列长度的二次/线性逐步结构。</li><li>各头仍可对同一 \\(K\\) 打出不同分数，但值子空间不再按头分化，这是质量损失的来源。</li><li>前填加速有限，生成越长、并发越高，收益越大。</li><li>从 MHA 改造通常需要合并 KV 投影并上训练；GQA 后来把这种合并变成可调组数。</li><li>张量并行难以按 KV 头切分，服务栈要单独处理。</li><li>出处：Shazeer, <em>Fast Transformer Decoding: One Write-Head is All You Need</em>, 2019。</li></ul>',11))])}const Q=E(B,[["render",m]]);export{_ as __pageData,Q as default};
